using System;
using System.Collections.Generic;
using System.Reflection;

internal static class Program
{
    private static int checks, failures, scenarios;
    private static void Check(bool condition,string name){checks++;if(!condition){failures++;Console.WriteLine("FAIL "+name);}}
    private static void Run(string name,Action action){scenarios++;try{action();}catch(Exception error){Check(false,name+" unexpected "+error.GetType().Name+": "+error.Message);}}
    private static Dictionary<string,Action<object>> Normal(EventManagerFixture value)=>(Dictionary<string,Action<object>>)typeof(EventManagerFixture).GetField("_eventWithObjectDictionary",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(value);
    private static Dictionary<string,Action<object>> Once(EventManagerFixture value)=>(Dictionary<string,Action<object>>)typeof(EventManagerFixture).GetField("_eventOnceObjectDictionary",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(value);
    private static void Throws<T>(Action action,string name) where T:Exception{Exception observed=null;try{action();}catch(Exception error){observed=error;}Check(observed is T,name);}
    private static void ThrowMarker(Exception marker){throw marker;}
    public static int Main()
    {
        Run("constructor",()=>{var e=new EventManagerFixture();Check(Normal(e)!=null,"normal dictionary initialized");Check(Once(e)!=null,"once dictionary initialized");Check(!ReferenceEquals(Normal(e),Once(e)),"dictionaries independent");Check(Normal(e).Count==0&&Once(e).Count==0,"dictionaries empty");});
        Run("normal order and payload",()=>{var e=new EventManagerFixture();var calls=new List<string>();var payload=new object();e.StartListening("x",p=>{Check(ReferenceEquals(p,payload),"first payload identity");calls.Add("a");});e.StartListening("x",p=>{Check(ReferenceEquals(p,payload),"second payload identity");calls.Add("b");});e.TriggerEvent("x",payload);Check(string.Join(",",calls)=="a,b","multicast registration order");});
        Run("persistent listeners",()=>{var e=new EventManagerFixture();int count=0;e.StartListening("x",_=>count++);e.TriggerEvent("x",null);e.TriggerEvent("x",null);Check(count==2,"normal listener persists");});
        Run("duplicates remove last",()=>{var e=new EventManagerFixture();int count=0;Action<object> callback=_=>count++;e.StartListening("x",callback);e.StartListening("x",callback);e.TriggerEvent("x",null);Check(count==2,"duplicate listeners both invoke");e.StopListening("x",callback);e.TriggerEvent("x",null);Check(count==3,"one duplicate removed");e.StopListening("x",callback);Check(Normal(e).ContainsKey("x")&&Normal(e)["x"]==null,"stop retains null-valued key");e.TriggerEvent("x",null);Check(count==3,"removed listeners not invoked");});
        Run("unknown stops",()=>{var e=new EventManagerFixture();e.StopListening("missing",_=>{});e.StopListeningOnce("missing",_=>{});Check(Normal(e).Count==0&&Once(e).Count==0,"unknown stops do not insert keys");e.TriggerEvent("missing",null);Check(Normal(e).Count==0&&Once(e).Count==0,"unknown trigger no mutation");});
        Run("null listener",()=>{var e=new EventManagerFixture();e.StartListening("x",null);Check(Normal(e).ContainsKey("x")&&Normal(e)["x"]==null,"null listener stored");e.TriggerEvent("x",null);int count=0;Action<object> callback=_=>count++;e.StartListening("x",callback);e.StopListening("x",null);e.TriggerEvent("x",null);Check(count==1,"new listener replaces null and null remove preserves");});
        Run("one shot order",()=>{var e=new EventManagerFixture();var calls=new List<string>();e.StartListening("x",_=>calls.Add("normal"));e.StartListeningOnce("x",_=>{Check(!Once(e).ContainsKey("x"),"once removed before first callback");calls.Add("once-a");});e.StartListeningOnce("x",_=>calls.Add("once-b"));e.TriggerEvent("x",null);e.TriggerEvent("x",null);Check(string.Join(",",calls)=="normal,once-a,once-b,normal","normal before once and once consumed");});
        Run("one shot reentry",()=>{var e=new EventManagerFixture();int normal=0,once=0;e.StartListening("x",_=>normal++);e.StartListeningOnce("x",_=>{once++;if(once<3)e.TriggerEvent("x",null);});e.TriggerEvent("x",null);Check(once==1,"once reentry cannot invoke consumed listener");Check(normal==2,"reentry still invokes normal listener");});
        Run("normal adds once for same dispatch",()=>{var e=new EventManagerFixture();var calls=new List<string>();e.StartListening("x",_=>{calls.Add("normal");e.StartListeningOnce("x",p=>calls.Add("new-once"));});e.TriggerEvent("x",null);Check(string.Join(",",calls)=="normal,new-once","once lookup happens after normal callbacks");});
        Run("normal removes once",()=>{var e=new EventManagerFixture();int count=0;Action<object> once=_=>count++;e.StartListeningOnce("x",once);e.StartListening("x",_=>e.StopListeningOnce("x",once));e.TriggerEvent("x",null);Check(count==0,"normal can cancel pending once");Check(Once(e).ContainsKey("x")&&Once(e)["x"]==null,"null once key retained when not invoked");});
        Run("once reregisters",()=>{var e=new EventManagerFixture();int first=0,second=0;e.StartListeningOnce("x",_=>{first++;e.StartListeningOnce("x",p=>second++);});e.TriggerEvent("x",null);Check(first==1&&second==0,"new once waits for next dispatch");Check(Once(e).ContainsKey("x"),"replacement once is not removed after callback");e.TriggerEvent("x",null);Check(first==1&&second==1,"replacement once survives");Check(!Once(e).ContainsKey("x"),"replacement consumed");});
        Run("normal exception",()=>{var e=new EventManagerFixture();var marker=new InvalidOperationException("native-contract-marker");int later=0,once=0;Action<object> throwing=_=>ThrowMarker(marker);e.StartListening("x",throwing);e.StartListening("x",_=>later++);e.StartListeningOnce("x",_=>once++);Exception observed=null;try{e.TriggerEvent("x",null);}catch(Exception error){observed=error;}Check(ReferenceEquals(observed,marker),"normal exception identity propagates");Check(observed!=null&&observed.StackTrace.Contains(nameof(ThrowMarker)),"origin frame retained");Check(later==0&&once==0,"normal exception aborts remaining callbacks");Check(Once(e).ContainsKey("x"),"once survives normal exception");e.StopListening("x",throwing);e.TriggerEvent("x",null);Check(later==1&&once==1,"later dispatch can consume retained once");});
        Run("once exception",()=>{var e=new EventManagerFixture();var marker=new ApplicationException("once-marker");int first=0,second=0;e.StartListeningOnce("x",_=>{first++;throw marker;});e.StartListeningOnce("x",_=>second++);Exception observed=null;try{e.TriggerEvent("x",null);}catch(Exception error){observed=error;}Check(ReferenceEquals(observed,marker),"once exception identity propagates");Check(!Once(e).ContainsKey("x"),"once consumed even when callback throws");Check(first==1&&second==0,"multicast once stops after exception");e.TriggerEvent("x",null);Check(first==1&&second==0,"throwing once does not recur");});
        Run("normal invocation snapshot",()=>{var e=new EventManagerFixture();var calls=new List<string>();Action<object> b=_=>calls.Add("b");e.StartListening("x",_=>{calls.Add("a");e.StopListening("x",b);});e.StartListening("x",b);e.TriggerEvent("x",null);e.TriggerEvent("x",null);Check(string.Join(",",calls)=="a,b,a","current multicast snapshot unaffected by remove");});
        Run("once remove duplicate",()=>{var e=new EventManagerFixture();int count=0;Action<object> a=_=>count++;e.StartListeningOnce("x",a);e.StartListeningOnce("x",a);e.StopListeningOnce("x",a);e.TriggerEvent("x",null);Check(count==1,"once stop removes one duplicate");Check(!Once(e).ContainsKey("x"),"remaining once consumed");});
        Run("event keys",()=>{var e=new EventManagerFixture();int lower=0,upper=0,empty=0;e.StartListening("x",_=>lower++);e.StartListening("X",_=>upper++);e.StartListening("",_=>empty++);e.TriggerEvent("x",null);e.TriggerEvent("",null);Check(lower==1&&upper==0&&empty==1,"dictionary case and empty-key behavior");});
        Run("null event keys",()=>{var e=new EventManagerFixture();Throws<ArgumentNullException>(()=>e.StartListening(null,_=>{}),"start null key throws");Throws<ArgumentNullException>(()=>e.StopListening(null,_=>{}),"stop null key throws");Throws<ArgumentNullException>(()=>e.StartListeningOnce(null,_=>{}),"start once null key throws");Throws<ArgumentNullException>(()=>e.StopListeningOnce(null,_=>{}),"stop once null key throws");Throws<ArgumentNullException>(()=>e.TriggerEvent(null,null),"trigger null key throws");});
        Run("optional null parameter",()=>{var e=new EventManagerFixture();object received=new object();e.StartListening("x",p=>received=p);e.TriggerEvent("x");Check(received==null,"omitted parameter is null rather than Missing.Value");var parameter=typeof(EventManagerFixture).GetMethod("TriggerEvent").GetParameters()[1];Check(parameter.IsOptional&&parameter.HasDefaultValue&&parameter.DefaultValue==null,"optional metadata preserves actual null default");});
        Run("immediate init",()=>{var e=new EventManagerFixture();int count=0;e.StartListening("x",_=>count++);var task=e.Init();Check(task.GetAwaiter().IsCompleted,"Init completed synchronously");task.GetAwaiter().GetResult();e.TriggerEvent("x",null);Check(count==1,"Init does not clear listeners or invoke callback");});
        Console.WriteLine($"EVENT_SOURCE_TESTS scenarios={scenarios} checks={checks} failures={failures}");
        return failures==0?0:1;
    }
}
